    getchar();
}

int main(int argc, char *argv[])
{
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <M> <L> <R>\n", argv[0]);
        return 1;
    }

    int m = atoi(argv[1]);
    int l = atoi(argv[2]);
    int r = atoi(argv[3]);

    if (m <= 0 || l < 1 || l > r) {
        fprintf(stderr, "Error: M > 0, L >= 1, L <= R required\n");
        return 1;
    }

    int *found = malloc((size_t)(r - l + 1) * sizeof(int));
    if (!found) {
        perror("malloc");
        return 1;
